mapper.select:
SELECT id, door_name doorName, event_time eventTime, event_name eventName, event_id eventId, person_id personId, person_name personName, event_type eventType, event_result eventResult, event_way eventWay, picture_file_id pictureFileId FROM event_record
and event_result = #{param.eventResult}
and event_time BETWEEN #{ param.beginTime} and #{param.endTime}
and door_name like concat('%',#{param.keyword},'%')
and door_index_code in
#{item}
order by event_time desc

SELECT a.id, a.door_name doorName, a.event_time eventTime, a.event_name eventName, a.event_id eventId, a.person_id personId, a.person_name personName, a.event_type eventType, a.event_result eventResult, a.event_way eventWay, a.picture_file_id pictureFileId FROM event_record a
and a.event_result = #{param.eventResult}
and a.event_time BETWEEN #{ param.beginTime} and #{param.endTime}
and a.door_name like concat('%',#{param.keyword},'%')
and a.door_index_code in
#{item}
order by a.event_time desc

SELECT COUNT(CASE WHEN in_and_out_type = '1' THEN 1 END) AS inNum, COUNT(CASE WHEN in_and_out_type = '0' THEN 1 END) AS outNum FROM event_record
and event_time >= #{param.period.begin}
and event_time <= #{param.period.end}
and door_name like concat('%',#{param.keyword},'%')

SELECT count(id) num,
TO_CHAR(event_time, ${timeFlag}) AS timeValue
date_format(event_time, ${timeFlag}) AS timeValue
FROM event_record
and event_time >= #{param.period.begin}
and event_time <= #{param.period.end}
and in_and_out_type = #{param.inAndOut}
and door_name like concat('%',#{param.keyword},'%')
group by TO_CHAR(event_time,${timeFlag})
group by date_format(event_time,${timeFlag})

SELECT
count(id) num
FROM event_record


        and event_time >= #{param.period.begin}


        and event_time <= #{param.period.end}


        and in_and_out_type = #{param.inAndOut}


        and door_name like concat('%',#{param.keyword},'%')

select event_name as name,count(id) as value from event_record
where deleted = 0

    and event_time >= #{param.period.begin}


    and event_time < #{param.period.end}

group by event_name
order by value desc
